/* MSG-01 · Mensajería.
   El system token no define blanco puro (§1.1); las superficies "blancas" del
   HTML aprobado usan var(--bw-warm-cream), la superficie clara más cercana. */

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
  margin-bottom: 4px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
  margin: 0 0 3px;
}

.subtitle {
  font-size: 14px;
  color: var(--bw-steel-mist);
  line-height: 1.6;
  margin: 0 0 16px;
  max-width: 560px;
}

.actionsBar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.searchWrap {
  position: relative;
  flex: 1;
  max-width: 300px;
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  font-size: 13px;
  color: var(--bw-deep-steel);
  outline: none;
  font-family: inherit;
  background: var(--bw-warm-cream);
  transition: border-color 0.15s;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.primaryBtn {
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  color: var(--bw-warm-cream);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  font-family: inherit;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  transition: opacity 0.12s;
}

.primaryBtn:not(:disabled):hover {
  opacity: 0.88;
}

.primaryBtn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.disabledReason {
  font-size: 12px;
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.threadCount {
  font-size: 12px;
  color: var(--bw-input-placeholder);
  margin-left: auto;
  white-space: nowrap;
}

.status {
  padding: 24px 0;
  font-size: 14px;
  color: var(--bw-steel-mist);
}

.error {
  padding: 12px 14px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 5px;
  background: var(--bw-sensitive-bg);
  color: var(--bw-sensitive-text);
  font-size: 14px;
  line-height: 1.5;
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn {
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-warm-cream);
  font-size: 12px;
  color: var(--bw-ink-steel);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: inherit;
  transition: border-color 0.12s, color 0.12s, opacity 0.12s;
}

.pageBtn:not(:disabled):hover {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageBtn:disabled {
  color: var(--bw-input-placeholder);
  cursor: not-allowed;
  opacity: 0.6;
}

.pageCurrent {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
  cursor: default;
}

.pageCurrent:disabled {
  color: var(--bw-warm-cream);
  opacity: 1;
  cursor: default;
}

