import { useEffect, useState } from 'react';
import type { MemberProfile } from '../../lib/session';
import { fetchThreadPage, pageCount, type ThreadSummary } from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * Pantalla MSG-01 · Lista de Hilos.
 *
 * Es LA pantalla: posee el estado de búsqueda y de página, llama a
 * `fetchThreadPage` con `profile.orgId` y renderiza `ThreadList`.
 *
 * F-118: `onOpenThread` se recibe del shell y NO se usa. MSG-02 no existía
 * cuando se escribió esta tarea, así que abrir un hilo no lleva a ningún sitio.
 * Por eso no se desestructura: la prop está en la firma pública para que
 * App.tsx compile, y aquí se ignora entera.
 */

/**
 * F-128: el error que enseña el aviso es el de verdad.
 *
 * PostgREST no lanza instancias de Error: rechaza con un objeto plano
 * `{ code, message }`, así que `String(e)` daría `[object Object]` y `e.message`
 * sería `undefined`. Se extraen `code` y `message` cuando existen y se pintan
 * junto a la frase para humanos.
 */
function errorDetail(err: unknown): string {
  if (err instanceof Error) {
    const code = (err as Error & { code?: unknown }).code;
    if (typeof code === 'string' && code) return `${code}: ${err.message}`;
    return err.message;
  }
  if (typeof err === 'object' && err !== null) {
    const rec = err as Record<string, unknown>;
    const code = typeof rec.code === 'string' ? rec.code : undefined;
    const message = typeof rec.message === 'string' ? rec.message : undefined;
    if (code && message) return `${code}: ${message}`;
    if (code) return code;
    if (message) return message;
    return JSON.stringify(rec) ?? '{}';
  }
  return String(err);
}

export function Messages({
  profile,
  now = new Date(),
}: {
  profile: MemberProfile;
  now?: Date;
  onOpenThread?: (threadId: string) => void;
}) {
  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<unknown>(null);
  const [search, setSearch] = useState('');
  const [query, setQuery] = useState('');
  const [page, setPage] = useState(1);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchThreadPage({ orgId: profile.orgId, search: query, page })
      .then((res) => {
        if (cancelled) return;
        setThreads(res.threads);
        setTotal(res.total);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [profile.orgId, query, page]);

  const pages = pageCount(total);

  const applySearch = () => {
    setQuery(search.trim());
    setPage(1);
  };

  return (
    <div aria-busy={loading}>
      <div className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</div>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a
        extremo.
      </p>

      <div className={styles.actionsBar}>
        <form
          className={styles.searchWrap}
          role="search"
          onSubmit={(e) => {
            e.preventDefault();
            applySearch();
          }}
        >
          <i className={`ti ti-search ${styles.searchIcon}`} aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            data-testid="search-input"
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar por nombre de organización"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                e.preventDefault();
                applySearch();
              }
            }}
          />
        </form>

        {/* F-023 e: "Nuevo contacto" abre DIR-01, que no está entre las 8
            pantallas del MVP. El control existe pero se pinta deshabilitado con
            el motivo, no como una acción que parece pulsable y no lleva a
            ninguna parte. */}
        <button
          type="button"
          className={styles.primaryBtn}
          disabled
          data-testid="nuevo-contacto"
          aria-describedby="nuevo-contacto-motivo"
          title="El Directorio queda fuera del MVP"
        >
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>
        <span id="nuevo-contacto-motivo" data-testid="nuevo-contacto-motivo" className={styles.disabledReason}>
          El Directorio queda fuera del MVP
        </span>

        <span className={styles.threadCount} data-testid="pag-info">
          {total.toLocaleString('es-ES')} {total === 1 ? 'hilo' : 'hilos'} · Página{' '}
          {page.toLocaleString('es-ES')} de {pages.toLocaleString('es-ES')}
        </span>
      </div>

      {loading && threads.length === 0 ? (
        <p role="status" className={styles.status}>
          Cargando hilos…
        </p>
      ) : error ? (
        /* F-127: el aviso lleva role="alert"; no sale gratis del HTML. */
        <div role="alert" className={styles.error}>
          No se pudieron cargar los hilos. {errorDetail(error)}
        </div>
      ) : (
        <>
          {/* MSG-02 no existe (F-118): abrir un hilo no lleva a ningún sitio y
              onOpenThread no se usa. ThreadList exige un onOpen; se le da un no-op. */}
          <ThreadList threads={threads} now={now} onOpen={() => {}} />
          <div className={styles.pagination}>
            <button
              type="button"
              className={styles.pageBtn}
              aria-label="Página anterior"
              disabled={page <= 1}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
            >
              ‹
            </button>
            {Array.from({ length: pages }, (_, i) => i + 1).map((p) => (
              <button
                key={p}
                type="button"
                className={`${styles.pageBtn} ${p === page ? styles.pageCurrent : ''}`}
                aria-current={p === page ? 'page' : undefined}
                disabled={p === page}
                onClick={() => setPage(p)}
              >
                {p}
              </button>
            ))}
            <button
              type="button"
              className={styles.pageBtn}
              aria-label="Página siguiente"
              disabled={page >= pages}
              onClick={() => setPage((p) => Math.min(pages, p + 1))}
            >
              ›
            </button>
          </div>
        </>
      )}
    </div>
  );
}

