import { previewLabel, relativeTime, stateTone, type ThreadSummary } from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * Lista de hilos de MSG-01.
 *
 * Presentacional: recibe los hilos en el orden que el servidor ya dejó (más
 * reciente primero) y los pinta tal cual. No consulta datos ni pagina; eso lo
 * posee `Messages`.
 *
 * F-131: cada hilo vive en un `<li>` que conserva su rol `listitem`. Lo que se
 * pulsa es un `<button>` DENTRO del `<li>`, y es ese botón el que lleva el
 * nombre accesible del hilo (aria-label con la contraparte). Un `role="button"`
 * sobre el `<li>` no suma al rol implícito: lo sustituye, y el contrato de
 * unidad consulta `listitem` nueve veces entre los dos ficheros.
 */
export function ThreadList({
  threads,
  now,
  onOpen,
}: {
  threads: ThreadSummary[];
  now?: Date;
  onOpen: (id: string) => void;
}) {
  if (threads.length === 0) {
    return (
      <div className={styles.empty} data-testid="empty-state">
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras
          organizaciones.
        </p>
        {/* F-128: el motivo del botón apagado es visible. Un botón que parece
            pulsable y no lleva a ninguna parte es F-023 llevado a la interfaz. */}
        <p className={styles.emptyHint}>El Directorio queda fuera del MVP</p>
        <button type="button" className={styles.emptyBtn} disabled data-testid="empty-button">
          Ir al Directorio
        </button>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => (
        <li key={thread.id} className={styles.row}>
          <div className={styles.rowGrid}>
            <span className={styles.top}>
              <span className={styles.org}>{thread.counterpartyName}</span>
              {thread.counterpartyCountry && (
                <span className={styles.countryBadge}>{thread.counterpartyCountry}</span>
              )}
            </span>
            <span className={styles.tsRow}>
              <span className={styles.ts}>{relativeTime(thread.lastItemAt, now)}</span>
            </span>
            <span className={styles.bot}>
              {/* La vista previa son METADATOS, nunca contenido descifrado (§7). */}
              <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
              <span className={`${styles.stateBadge} ${styles[stateTone(thread.state)]}`}>
                {thread.state}
              </span>
            </span>
          </div>
          <button
            type="button"
            className={styles.rowButton}
            aria-label={thread.counterpartyName}
            onClick={() => onOpen(thread.id)}
          />
        </li>
      ))}
    </ul>
  );
}
